import datetime
import re

class ValidationError(Exception):
    """Raised when validation fails"""
    pass

class PaymentCardValidator:
    def __init__(self):
        self.valid_fields = {
            "card_token", "card_number", "expiry_month", "expiry_year",
            "cvv", "cardholder_name", "billing_address", "metadata"
        }
        self.valid_address_fields = {"street", "city", "state", "postal_code", "country"}
        self.valid_states = {
            'AL', 'AK', 'AZ', 'AR', 'CA', 'CO', 'CT', 'DE', 'FL', 'GA',
            'HI', 'ID', 'IL', 'IN', 'IA', 'KS', 'KY', 'LA', 'ME', 'MD',
            'MA', 'MI', 'MN', 'MS', 'MO', 'MT', 'NE', 'NV', 'NH', 'NJ',
            'NM', 'NY', 'NC', 'ND', 'OH', 'OK', 'OR', 'PA', 'RI', 'SC',
            'SD', 'TN', 'TX', 'UT', 'VT', 'VA', 'WA', 'WV', 'WI', 'WY',
            'AS', 'DC', 'FM', 'GU', 'MH', 'MP', 'PW', 'PR', 'VI'
        }  # US states and territories

    def validate(self, payload):
        """
        Validates a payment card tokenization payload

        Args:
            payload: Dict containing the payment card data

        Returns:
            True if valid

        Raises:
            ValidationError: With detailed error message if validation fails
        """
        if not isinstance(payload, dict):
            raise ValidationError("Payload must be a dictionary")

        # Check for extra fields at root level
        extra_fields = set(payload.keys()) - self.valid_fields
        if extra_fields:
            raise ValidationError(f"Extra fields not allowed: {', '.join(sorted(extra_fields))}")

        errors = []

        # Validate required fields
        for field in self.valid_fields:
            if field == "metadata":  # metadata is optional
                continue
            if field not in payload:
                errors.append(f"Missing required field: {field}")

        if errors:
            raise ValidationError("; ".join(errors))

        # Validate individual fields
        try:
            self._validate_card_token(payload["card_token"])
        except ValidationError as e:
            errors.append(f"card_token: {str(e)}")

        try:
            self._validate_card_number(payload["card_number"])
        except ValidationError as e:
            errors.append(f"card_number: {str(e)}")

        try:
            self._validate_expiry(payload["expiry_month"], payload["expiry_year"])
        except ValidationError as e:
            errors.append(f"expiry: {str(e)}")

        try:
            self._validate_cvv(payload["cvv"])
        except ValidationError as e:
            errors.append(f"cvv: {str(e)}")

        try:
            self._validate_cardholder_name(payload["cardholder_name"])
        except ValidationError as e:
            errors.append(f"cardholder_name: {str(e)}")

        try:
            self._validate_billing_address(payload["billing_address"])
        except ValidationError as e:
            errors.append(f"billing_address: {str(e)}")

        if "metadata" in payload and payload["metadata"] is not None:
            try:
                self._validate_metadata(payload["metadata"])
            except ValidationError as e:
                errors.append(f"metadata: {str(e)}")

        if errors:
            raise ValidationError("; ".join(errors))

        return True

    def _validate_card_token(self, token):
        """Validate card token format"""
        if token is None:
            raise ValidationError("Cannot be null")
        if not isinstance(token, str):
            raise ValidationError("Must be a string")
        if not token.startswith("tok_"):
            raise ValidationError("Must start with 'tok_' prefix")
        if len(token) < 8:  # tok_ + at least 3 chars
            raise ValidationError("Invalid token format")
        return True

    def _validate_card_number(self, card_number):
        """Validate card number format and Luhn check"""
        if card_number is None:
            raise ValidationError("Cannot be null")
        if not isinstance(card_number, str):
            raise ValidationError("Must be a string")
        if not card_number.isdigit():
            raise ValidationError("Must contain only digits")
        if len(card_number) < 13 or len(card_number) > 19:
            raise ValidationError("Must be 13-19 digits")
        if not self._luhn_check(card_number):
            raise ValidationError("Failed Luhn validation")
        return True

    def _luhn_check(self, card_number):
        """Perform Luhn algorithm validation"""
        sum = 0
        is_even = False
        for digit in reversed(card_number):
            n = int(digit)
            if is_even:
                n *= 2
                if n > 9:
                    n -= 9
            sum += n
            is_even = not is_even
        return sum % 10 == 0

    def _validate_expiry(self, month, year):
        """Validate expiry month and year"""
        errors = []

        # Validate month
        if month is None:
            errors.append("expiry_month cannot be null")
        elif not isinstance(month, int):
            errors.append("expiry_month must be an integer")
        elif month < 1 or month > 12:
            errors.append("expiry_month must be between 1 and 12")

        # Validate year
        if year is None:
            errors.append("expiry_year cannot be null")
        elif not isinstance(year, int):
            errors.append("expiry_year must be an integer")

        if errors:
            raise ValidationError(", ".join(errors))

        # Check if card is expired
        current_year = datetime.datetime.now().year
        current_month = datetime.datetime.now().month

        if year < current_year:
            raise ValidationError("Card is expired (year is in the past)")
        elif year == current_year and month < current_month:
            raise ValidationError("Card is expired (month is in the past)")

        return True

    def _validate_cvv(self, cvv):
        """Validate CVV"""
        if cvv is None:
            raise ValidationError("Cannot be null")  
        if not isinstance(cvv, (str, int)):
            raise ValidationError("Must be a string or integer")
        cvv_str = str(cvv)
        if not cvv_str.isdigit():
            raise ValidationError("Must contain only digits")
        if len(cvv_str) < 3 or len(cvv_str) > 4:
            raise ValidationError("Must be 3 or 4 digits")
        return True

    def _validate_cardholder_name(self, name):
        """Validate cardholder name"""
        if name is None:
            raise ValidationError("Cannot be null")
        if not isinstance(name, str):
            raise ValidationError("Must be a string")
        if not name or len(name.strip()) == 0:
            raise ValidationError("Must not be empty")
        if len(name) < 2 or len(name) > 50:
            raise ValidationError("Must be 2-50 characters")
        return True

    def _validate_billing_address(self, address):
        """Validate billing address"""
        if address is None:
            raise ValidationError("Cannot be null")
        if not isinstance(address, dict):
            raise ValidationError("Must be an object")

        # Check for extra fields
        extra_fields = set(address.keys()) - self.valid_address_fields
        if extra_fields:
            raise ValidationError(f"Extra fields not allowed: {', '.join(sorted(extra_fields))}")

        errors = []

        # Validate required address fields
        for field in self.valid_address_fields:
            if field not in address:
                errors.append(f"Missing required field: {field}")

        if errors:
            raise ValidationError("; ".join(errors))

        # Validate street
        try:
            self._validate_street(address["street"])
        except ValidationError as e:
            errors.append(f"street: {str(e)}")

        # Validate city
        try:
            self._validate_city(address["city"])
        except ValidationError as e:
            errors.append(f"city: {str(e)}")

        # Validate state
        try:
            self._validate_state(address["state"])
        except ValidationError as e:
            errors.append(f"state: {str(e)}")

        # Validate postal_code
        try:
            self._validate_postal_code(address["postal_code"])
        except ValidationError as e:
            errors.append(f"postal_code: {str(e)}")

        # Validate country
        try:
            self._validate_country(address["country"])
        except ValidationError as e:
            errors.append(f"country: {str(e)}")

        if errors:
            raise ValidationError("; ".join(errors))

        return True

    def _validate_street(self, street):
        """Validate street address"""
        if street is None:
            raise ValidationError("Cannot be null")
        if not isinstance(street, str):
            raise ValidationError("Must be a string")
        if not street or len(street.strip()) == 0:
            raise ValidationError("Must not be empty")
        return True

    def _validate_city(self, city):
        """Validate city"""
        if city is None:
            raise ValidationError("Cannot be null")
        if not isinstance(city, str):
            raise ValidationError("Must be a string")
        if not city or len(city.strip()) == 0:
            raise ValidationError("Must not be empty")
        return True

    def _validate_state(self, state):
        """Validate state code"""
        if state is None:
            raise ValidationError("Cannot be null")
        if not isinstance(state, str):
            raise ValidationError("Must be a string")
        if len(state) != 2:
            raise ValidationError("Must be exactly 2 characters")
        if state.upper() not in self.valid_states:
            raise ValidationError("Invalid US state code")
        return True

    def _validate_postal_code(self, postal_code):
        """Validate postal code"""
        if postal_code is None:
            raise ValidationError("Cannot be null")
        if not isinstance(postal_code, str):
            raise ValidationError("Must be a string")
        if not postal_code or len(postal_code.strip()) == 0:
            raise ValidationError("Must not be empty")
        # Allow alphanumeric and dashes
        if not re.match(r'^[a-zA-Z0-9\-]+$', postal_code):
            raise ValidationError("Must contain only alphanumeric characters and dashes")
        return True

    def _validate_country(self, country):
        """Validate country code"""
        if country is None:
            raise ValidationError("Cannot be null")
        if not isinstance(country, str):
            raise ValidationError("Must be a string")
        if len(country) != 2:
            raise ValidationError("Must be exactly 2 characters")
        if not country.isalpha():
            raise ValidationError("Must contain only letters")
        # We'll be flexible on valid countries and just enforce format
        # since the list in requirements is limited
        return True

    def _validate_metadata(self, metadata):
        """Validate metadata object"""
        if metadata is None:
            return True  # None metadata is treated as valid
        if not isinstance(metadata, dict):
            raise ValidationError("Must be an object")

        errors = []

        for key, value in metadata.items():
            if not isinstance(key, str):
                errors.append(f"Metadata key '{key}' must be a string")
                continue
            if not isinstance(value, str):
                errors.append(f"Metadata value for '{key}' must be a string, got {type(value).__name__}")
            elif not value or len(value.strip()) == 0:
                errors.append(f"Metadata value for '{key}' cannot be empty")

        if errors:
            raise ValidationError("; ".join(errors))

        return True

