    def _luhn_check(self, card_number):
        """Perform Luhn algorithm validation"""
        total_sum = 0
        is_even = False
        for digit in reversed(card_number):
            n = int(digit)
            if is_even:
                n *= 2
                if n > 9:
                    n -= 9
            total_sum += n
            is_even = not is_even
        return total_sum % 10 == 0

