        if not self._luhn_check(card_number):
            raise ValidationError("Failed Luhn validation")
        return True

    def _luhn_check(self, card_number):
        """Perform Luhn algorithm validation"""
        sum = 0
        is_even = False
        for digit in reversed(card_number):
            n = int(digit)
            if is_even:
                n *= 2
                if n > 9:
                    n -= 9
            sum += n
            is_even = not is_even
        return sum % 10 == 0

