        upper_stripped = stripped.upper()
        for pattern in self.postal_code_patterns:
            if re.match(pattern, upper_stripped):
                return True

        # If no pattern matches but format is valid, still accept (for flexibility)
        # Just ensure it's not too short or too long
        if len(stripped) > 20:
